package com.careerorbit.service;
import com.careerorbit.ai.ChatGateway;import com.careerorbit.entity.*;import com.careerorbit.mapper.QuestionSetMapper;import com.careerorbit.security.CurrentUser;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.Test;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class QuestionGenerationServiceTest {@Test void generationDeduplicatesQuestionsBeforePersisting()throws Exception{var resumes=mock(ResumeService.class);var resume=new ResumeEntity();resume.id=1L;resume.parsedJson="{}";when(resumes.get(1)).thenReturn(resume);var rag=mock(RagService.class);when(rag.search(anyString(),anyInt())).thenReturn(List.of(new RagService.RagHit("c",1,"t","content","c","java","m","s",1)));var chat=mock(ChatGateway.class);when(chat.json(anyString(),any(TypeReference.class))).thenReturn(List.of(Map.of("question","同一道题"),Map.of("question","同一道题"),Map.of("question","另一题")));var mapper=mock(QuestionSetMapper.class);var current=mock(CurrentUser.class);var user=new UserEntity();user.id=7L;when(current.require()).thenReturn(user);var service=new QuestionGenerationService(resumes,rag,chat,mapper,current,new ObjectMapper());var result=service.generate(new QuestionGenerationService.GenerateCommand(1,"Java","JD","Java","中级",10,List.of("技术")));assertThat(result.questionsJson).contains("同一道题","另一题");assertThat(new ObjectMapper().readTree(result.questionsJson)).hasSize(2);verify(mapper).insert(result);}}
